from cardio_1 import a, G
# Les codes principaux existent déjà ; les termes sont écrits en toutes lettres.
a('SCN9A', [('SCN', 'Sodium Channel, voltage-gated : canal sodique voltage-dépendant'), ('9', 'famille 9'), ('A', 'sous-unité alpha')], 'Gène codant le canal sodique neuronal Nav1.7', '<p>Certains variants avec gain de fonction augmentent l’excitabilité neuronale et peuvent provoquer une érythromélalgie familiale. Le résultat génétique s’interprète selon la classification du variant et le phénotype.</p>')
a('ACVRL1', [('ACVR', 'Activin Receptor'), ('L', 'Like'), ('1', 'type 1')], 'Gène du récepteur de type activine impliqué dans la signalisation endothéliale', '<p>Un variant causal peut provoquer une télangiectasie hémorragique héréditaire. Le dépistage familial ne se résume pas à l’absence de symptômes visibles.</p>')
a('ENG', [('ENG', 'symbole officiel du gène de l’endogline ; il ne constitue pas un acronyme lettre par lettre')], 'Gène de l’endogline', '<p>Un variant pathogène peut perturber la signalisation endothéliale et provoquer la maladie de Rendu-Osler. Un variant de signification incertaine ne confirme pas ce diagnostic.</p>')
a('SEDUCE', [('S', 'Sildenafil'), ('E', 'Effect'), ('D', 'Digital'), ('U', 'Ulcer'), ('C', 'sClerodErma, lettre C interne au mot'), ('E', 'sClerodErma, lettre E interne au mot')], 'Sildenafil Effect on Digital Ulcer Healing in sClerodErma', '<p>Essai contrôlé contre placebo sur les ulcères digitaux sclérodermiques, publié en 2016. Il ne doit pas être confondu avec un essai cardiologique portant le même nom. Son critère principal de délai de cicatrisation n’a pas été atteint.</p>', 'i73-sildenafil')
a('CHUV', [('C', 'Centre'), ('H', 'Hospitalier'), ('U', 'Universitaire'), ('V', 'Vaudois')], 'Centre hospitalier universitaire vaudois', '<p>Institution suisse qui propose notamment une capillaroscopie en angiologie. La page clinique décrit l’examen morphologique des capillaires périunguéaux.</p>')
a('Rendu-Osler', [('Rendu', 'Henri Rendu, nom propre'), ('Osler', 'William Osler, nom propre')], 'Télangiectasie hémorragique héréditaire', '<p>Éponyme, et non abréviation. La maladie associe des télangiectasies et des malformations artérioveineuses ; ses critères cliniques sont ceux de Curaçao.</p>', 'i73-hht')
